// Validate + build a new ticket (spec §5.2, §6.1 phase 1 Intake).
// Server is authoritative — never trust the client (§8.2.2).
const body = $input.first().json.body || {};

const trim = (v) => (typeof v === 'string' ? v.trim() : v);
const esc = (v) => String(v == null ? '' : v)
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
  .replace(/"/g,'&quot;').replace(/'/g,'&#39;');

const EQUIP = ['hvac','refrigeration','electrical','plumbing','appliance','other'];
const data = {
  customer_name: trim(body.customer_name),
  customer_phone: trim(body.customer_phone),
  equipment_type: trim(body.equipment_type),
  symptom_description: trim(body.symptom_description),
  customer_address: trim(body.customer_address) || null,
};

const fields = {};
if (!data.customer_name || data.customer_name.length < 2 || data.customer_name.length > 80)
  fields.customer_name = 'Nombre de 2 a 80 caracteres.';
if (!/^\+[1-9][0-9]{7,14}$/.test(data.customer_phone || ''))
  fields.customer_phone = 'Teléfono en formato E.164 (+34600111222).';
if (!EQUIP.includes(data.equipment_type))
  fields.equipment_type = 'Tipo de equipo no válido.';
if (!data.symptom_description || data.symptom_description.length < 5 || data.symptom_description.length > 1000)
  fields.symptom_description = 'Descripción de 5 a 1000 caracteres.';
if (data.customer_address && data.customer_address.length > 200)
  fields.customer_address = 'Dirección máx. 200 caracteres.';

if (Object.keys(fields).length) {
  return [{ json: { __error: { code: 'VALIDATION_FAILED', message: 'Datos no válidos.', fields }, __status: 422 } }];
}

// Build the ticket
const now = new Date().toISOString();
const year = new Date().getFullYear();
const seq = String(Date.now()).slice(-6); // datastore should replace with a real sequence
const ticket_id = `FSC-${year}-${seq}`;
const access_token = (globalThis.crypto && crypto.randomUUID ? crypto.randomUUID() : (Date.now()+''+Math.random())).replace(/-/g,'') + Math.random().toString(36).slice(2,10);

const ticket = {
  ticket_id,
  customer_name: esc(data.customer_name),
  customer_phone: data.customer_phone,
  equipment_type: data.equipment_type,
  symptom_description: esc(data.symptom_description),
  status: 'Intake',
  assigned_technician: null,
  eta: null,
  customer_address: data.customer_address ? esc(data.customer_address) : null,
  priority: 'normal',
  access_token,
  created_at: now,
  updated_at: now,
  notified_events: [],
  notification_status: null,
  audit_log: [{ at: now, actor: 'system', from_status: null, to_status: 'Intake', note: 'created via intake form' }],
  idempotency_key: body.idempotency_key || ticket_id
};
return [{ json: { ticket } }];

// Emit fsc.v1.ticket.created (spec §4.2) and hand off to Notify (T1, §7).
const ticket = $('Validate & Build Ticket').first().json.ticket;
return [{ json: {
  event: 'fsc.v1.ticket.created',
  ticket_id: ticket.ticket_id,
  occurred_at: new Date().toISOString(),
  actor: 'system',
  data: ticket,
  notify_template: 'T1'
} }];
